"use server";

import {
  readContactValues,
  successMessage,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from "@/lib/contact";

export type ContactState = {
  values: ContactValues;
  errors: ContactErrors;
  success: string | null;
};

export async function sendContact(
  _prev: ContactState,
  formData: FormData,
): Promise<ContactState> {
  const values = readContactValues(formData);
  const errors = validateContact(values);
  if (Object.keys(errors).length > 0) {
    return { values, errors, success: null };
  }
  return {
    values: { name: "", email: "", message: "" },
    errors: {},
    success: successMessage(values.name),
  };
}
EOF
cat > components/ContactForm.tsx <<'EOF'
"use client";

import { startTransition, useActionState, useState, type FormEvent } from "react";
import { sendContact, type ContactState } from "@/app/contact/actions";
import {
  readContactValues,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from "@/lib/contact";

const initialState: ContactState = {
  values: { name: "", email: "", message: "" },
  errors: {},
  success: null,
};

export default function ContactForm() {
  const [state, formAction, pending] = useActionState(sendContact, initialState);
  const [values, setValues] = useState<ContactValues>(state.values);
  const [clientErrors, setClientErrors] = useState<ContactErrors | null>(null);
  const [lastState, setLastState] = useState(state);

  // Sync fields with a new server answer (e.g. cleared after success).
  if (lastState !== state) {
    setLastState(state);
    setValues(state.values);
  }

  const errors = clientErrors ?? state.errors;
  const success = clientErrors ? null : state.success;

  function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const found = validateContact(readContactValues(formData));
    if (Object.keys(found).length > 0) {
      setClientErrors(found);
      return;
    }
    setClientErrors(null);
    startTransition(() => formAction(formData));
  }

  const field =
    (key: keyof ContactValues) =>
    (event: { target: { value: string } }) =>
      setValues((current) => ({ ...current, [key]: event.target.value }));

  return (
    <>
      {success && (
        <p className="success" role="status">
          {success}
        </p>
      )}
      <form action={formAction} onSubmit={onSubmit} noValidate>
        <div className="field">
          <label htmlFor="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            value={values.name}
            onChange={field("name")}
            aria-invalid={errors.name ? true : undefined}
            aria-describedby={errors.name ? "contact-name-error" : undefined}
          />
          {errors.name && (
            <p className="error" id="contact-name-error">
              {errors.name}
            </p>
          )}
        </div>
        <div className="field">
          <label htmlFor="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            value={values.email}
            onChange={field("email")}
            aria-invalid={errors.email ? true : undefined}
            aria-describedby={errors.email ? "contact-email-error" : undefined}
          />
          {errors.email && (
            <p className="error" id="contact-email-error">
              {errors.email}
            </p>
          )}
        </div>
        <div className="field">
          <label htmlFor="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={5}
            value={values.message}
            onChange={field("message")}
            aria-invalid={errors.message ? true : undefined}
            aria-describedby={
              errors.message ? "contact-message-error" : undefined
            }
          />
          {errors.message && (
            <p className="error" id="contact-message-error">
              {errors.message}
            </p>
          )}
        </div>
        <button type="submit" disabled={pending}>
          Send
        </button>
      </form>
    </>
  );
}
EOF
