import fs from "node:fs/promises";
import path from "node:path";
import { NextResponse, type NextRequest } from "next/server";

const BOOKS_DIR = path.join(process.cwd(), "content", "books");

export const config = {
  matcher: "/books/:slug",
};

// Unknown book slugs are answered with the 404 page before rendering starts,
// so the response keeps its 404 status instead of streaming a soft 404.
export async function proxy(request: NextRequest) {
  const slug = decodeURIComponent(
    request.nextUrl.pathname.slice("/books/".length),
  );
  let files: string[] = [];
  try {
    files = await fs.readdir(BOOKS_DIR);
  } catch {
    // Treat an unreadable directory as having no books.
  }
  if (files.includes(`${slug}.md`)) return NextResponse.next();
  return NextResponse.rewrite(new URL("/_missing-book", request.url), {
    status: 404,
  });
}
EOF
